import React, { useState, useEffect, useMemo } from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

// The tiles are rolled up from the very same catalogue rows the grid below shows,
// filtered the same way, so they respond to every filter - not just the ones that
// re-run SQL - and can never disagree with the table.
const STAGES = ["Integrity Check", "Data Verification I", "Data Verification II",
                "Data Audit I", "Data Audit II", "Unmapped"];
const n = (v) => (Number(v) || 0).toLocaleString();
const num = (v) => Number(v) || 0;

function App() {
  const [model, setModel] = useState(appsmith.model || {});
  useEffect(() => {
    const update = () => setModel({ ...(appsmith.model || {}) });
    update();
    if (typeof appsmith.onModelChange === "function") appsmith.onModelChange(update);
    const id = setInterval(update, 400);
    return () => clearInterval(id);
  }, []);

  const data = (model && model.data) || [];
  const stage = model.stage || "";
  const sev = model.sev || "";
  const cat = model.cat || "";
  const q = model.q || "";

  // Identical predicate to the grid's.
  const rows = useMemo(() => {
    const needle = String(q).trim().toLowerCase();
    return data.filter((r) => {
      if (stage && String(r["Stage"]) !== stage) return false;
      if (sev && String(r["Severity"]) !== sev) return false;
      if (cat && String(r["Category"]) !== cat) return false;
      if (!needle) return true;
      return String(r["Code"]).indexOf(needle) !== -1 ||
             String(r["Check"] || "").toLowerCase().indexOf(needle) !== -1;
    });
  }, [data, stage, sev, cat, q]);

  if (model.isLoading) return React.createElement("div", { className: "skel" }, "Loading stage totals...");
  if (!data.length) return React.createElement("div", { className: "skel" }, "No validation errors in this window.");

  const roll = (list) => {
    let total = 0, open = 0, blocked = 0, resolved = 0;
    list.forEach((r) => {
      total += num(r["Occurrences"]);
      open += num(r["Open"]);
      resolved += num(r["Resolved"]);
      // Resolvable is a property of the code, so open rows on a code that offers
      // no resolution path are the backlog nobody can clear.
      if (!r["Resolvable"]) blocked += num(r["Open"]);
    });
    return { total: total, open: open, blocked: blocked,
             pct: total ? Math.round(1000 * resolved / total) / 10 : null };
  };

  const tile = (label, t) =>
    React.createElement("div", { className: "tile", key: label },
      React.createElement("div", { className: "lbl" }, label),
      React.createElement("div", { className: "big" }, n(t.open)),
      // Say "errors", because the grid below counts codes and these count
      // occurrences - 6.5m errors collapsing into 75 codes reads like a bug
      // unless the units are on screen.
      React.createElement("div", { className: "sub" }, "open of " + n(t.total) + " errors" +
        (t.pct == null ? "" : "  ·  " + t.pct + "% resolved")),
      t.blocked > 0
        ? React.createElement("div", { className: "blocked" }, n(t.blocked) + " not resolvable")
        : React.createElement("div", { className: "ok" }, "all resolvable"));

  // Any stage the data carries that is not in the canonical list still gets a tile.
  const extra = [];
  rows.forEach((r) => {
    const s = r["Stage"];
    if (s && STAGES.indexOf(s) === -1 && extra.indexOf(s) === -1) extra.push(s);
  });

  return React.createElement("div", { className: "wrap" },
    React.createElement("div", { className: "tiles" },
      [tile("All Stages", roll(rows))].concat(
        STAGES.concat(extra.sort()).map((s) =>
          tile(s, roll(rows.filter((r) => r["Stage"] === s)))))));
}

ReactDOM.render(React.createElement(App, null), document.getElementById("root"));

